// Original high-resolution Garuda graphic, preserved without resampling.
// Pinned source and sizing reference: docs/third-party-notices/thai-garuda.md (copied unchanged).
// Embedded for offline exports; never resolve renderer-supplied paths or URLs.
const PNG_BASE64 =
  '';
// Web: decoded with atob (browser and Node) instead of Node's Buffer.
export const GARUDA_PNG = Uint8Array.from(atob(PNG_BASE64), (c) => c.charCodeAt(0));
export const GARUDA_DATA_URI = `data:image/png;base64,${PNG_BASE64}`;
